(() => {
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-SG',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100),when=s=>new Date(s).toLocaleString('en-SG');
const names={overview:'Overview',imports:'Data imports',checks:'Reconciliation',agent:'AI Agent',reports:'Reports & approvals',evidence:'Evidence & history',connections:'Connections'};
const schemas={payroll:['id','name','department','costCenter','period','basePay','allowances','deductions','netPaid','evidence'],ledger:['id','date','type','category','department','costCenter','amount','currency','reference','evidence','description'],bank:['id','date','direction','amount','currency','reference','description']};
const fieldLabel=k=>k==='id'?'ID':k.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase());
const labels={payroll:'Payroll',ledger:'Financial ledger',bank:'Bank statement'};
const statuses={draft:'Awaiting finance review',reviewed:'Awaiting director approval',approved:'Approved',rejected:'Returned'};
let questionDraft='Use bank_reconciliation to find unmatched records; if all rows match, choose one matched pair. Use read_source to verify the ledger and bank amounts. Cite both actual source IDs in square brackets. State the two amounts and whether they match, then recommend human verification. Keep under 100 words. Do not infer the contents of supporting documents.';
let state,providers,runs=[],role='finance',kind='payroll',selectedReport,preview,upload,toastTimer,pollTimer,busy=false;
const view=()=>names[location.hash.slice(1)]?location.hash.slice(1):'overview';
const btn=(label,action,attrs='',primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}" ${attrs}>${label}</button>`;
const badge=(label,type='')=>`<span class="badge ${type}">${esc(label)}</span>`;
const head=(title,detail,actions='')=>`<div class="page-header"><div><div class="eyebrow">PEOPLELEDGER / INTEGRATED WORKSPACE</div><h1>${title}</h1><p>${detail}</p></div><div class="actions">${actions}</div></div>`;
const card=(title,body,actions='')=>`<section class="card"><div class="card-head"><h2>${title}</h2>${actions}</div><div class="card-body">${body}</div></section>`;
function toast(text,error=false){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',6500);}
async function api(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-PeopleLedger-Request':'1'}:undefined,body:data?JSON.stringify(data):undefined});let body;try{body=await r.json();}catch{throw new Error('The local backend is unavailable. Start the full application with npm start.');}if(!r.ok)throw new Error(body.error||'Request failed');return body;}
async function refresh(){state=await api('workspace');render();}
function navigate(v){location.hash=v;}
function table(rows,fields,edit=false){if(!rows.length)return '<p class="muted">No records imported yet.</p>';return `<div class="table-wrap"><table><thead><tr>${fields.map(k=>`<th>${esc(fieldLabel(k))}</th>`).join('')}${edit?'<th>Action</th>':''}</tr></thead><tbody>${rows.map(r=>`<tr>${fields.map(k=>`<td>${esc(r[k])}</td>`).join('')}${edit?`<td>${btn('Edit','edit',`data-id="${esc(r.id)}" ${role===(kind==='payroll'?'hr':'finance')?'':'disabled'}`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function findings(a){return a.issues.length?`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Finding</th><th>Details</th></tr></thead><tbody>${a.issues.map(i=>`<tr><td>${esc(i.source)}<small class="source-rule">${esc(i.rule)}</small></td><td>${esc(i.title)}</td><td class="wrap-cell">${esc(i.detail)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="intro-line">No findings under the configured rules. Human review is still required.</div>';}
function stats(items){return `<div class="stats">${items.map(([l,v,d])=>`<div class="stat"><div class="stat-label">${l}</div><div class="stat-number">${v}</div><div class="stat-foot">${d}</div></div>`).join('')}</div>`;}
function overview(){const a=state.analysis;return head('Integrated review workspace','Import business files, reconcile payments and prepare an evidence-based review.',btn('Import files','nav','data-view="imports"',true))+
 stats([['Payroll records',state.datasets.payroll.length,'One payroll month per import'],['Ledger records',state.datasets.ledger.length,'Income and expense cash movements'],['Matched payments',a.reconciliation.matched,'Unique ledger ↔ bank matches'],['Open findings',a.issues.length,`Workspace version ${state.revision}`]])+
 `<div class="overview-guide"><strong>Review flow</strong><p>Excel / CSV → stored records → reconciliation → Agent draft → finance review → director decision.</p></div>`+
 `<div class="columns">${card('Imported data',Object.entries(state.datasets).map(([k,r])=>`<div class="connection-line"><div><strong>${labels[k]}</strong><p class="muted">${r.length} records · ${state.imports.filter(i=>i.kind===k).at(-1)?.filename?esc(state.imports.filter(i=>i.kind===k).at(-1).filename):'Awaiting file'}</p></div>${badge(r.length?'Imported':'Empty',r.length?'success':'')}</div>`).join(''))}${card('Cash movement · SGD',`<div class="metric-line"><span>Ledger income</span><strong>${money(a.finance.income)}</strong></div><div class="metric-line"><span>Ledger expenses</span><strong>${money(a.finance.expense)}</strong></div><div class="metric-line"><span>Net movement</span><strong>${money(a.finance.netMovement)}</strong></div><p class="footnote">Cash movement from imported rows; this is not a full accrual profit and loss statement.</p>`)}</div>`+
 card('Items requiring review',findings({...a,issues:a.issues.slice(0,8)}),btn('View all findings','nav','data-view="checks"'));}
function imports(){return head('Data imports','Preview files before replacing a dataset. Changes create a new workspace version.')+
 card('Import a business file',`<form id="import-form"><div class="form-grid"><label class="field">Dataset<select id="dataset" name="kind">${Object.entries(labels).map(([k,l])=>`<option value="${k}" ${kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label class="field">Excel or CSV file<input name="file" type="file" accept=".xlsx,.csv" required></label></div><div class="import-actions"><button class="btn primary" type="submit">Preview import</button><a class="btn" href="/examples/${kind==='payroll'?'payroll-corrected':kind+'-demo'}.csv" download>Download CSV example</a><a class="btn" href="/examples/${kind}.xlsx" download>Download Excel example</a></div><p class="footnote">${kind==='payroll'?'One payroll month; employee IDs must be unique. ':'Amounts are positive; direction or type determines inflow/outflow. '}${kind==='payroll'?'Import and edit as HR specialist.':'Import and edit as Finance reviewer.'} Up to 500 rows / 5 MB. Use the example headers; save Excel formulas as values. Imports replace this dataset and preserve report history.</p></form>`)+
 card(labels[kind]+' records',table(state.datasets[kind],schemas[kind],true),badge(`${state.datasets[kind].length} records`)+(kind==='payroll'&&state.datasets.payroll.length?btn('Export payroll CSV','payroll-csv') : ''))+
 card('Import history',state.imports.length?table(state.imports.slice().reverse(),['kind','filename','count','revision','at']):'<p class="muted">No files have been committed.</p>');}
function checks(){const a=state.analysis;return head('Reconciliation','Calculated on the server from current payroll, ledger, bank records and supporting files.',btn('Create rule report','rule-report',role==='finance'?'':'disabled',true))+
 stats([['Ledger income · SGD',money(a.finance.income),'Positive income rows'],['Ledger expense · SGD',money(a.finance.expense),'Positive expense rows'],['Expected net pay · SGD',money(a.payroll.expected),'Gross pay − entered deductions'],['Open findings',a.issues.length,'Blocking until resolved']])+
 card('Ledger ↔ bank matches',`<p class="footnote">${esc(a.reconciliation.method)}</p>${table(a.reconciliation.rows.map(r=>({...r,bankIds:r.bankIds.join(', ')})),['ledgerId','reference','amount','direction','status','bankIds'])}`)+
 card('Payroll, documents and payment findings',findings(a),badge(a.ruleVersion));}
function providerChoices(){let options=[];if(providers?.ollama)options=providers.ollama.models.map(m=>`<option value="ollama|${esc(m)}">Local · ${esc(m)}</option>`);if(providers?.bedrock.model)options.push(`<option value="bedrock|${esc(providers.bedrock.model)}">AWS · ${esc(providers.bedrock.model)}</option>`);return options.join('');}
function traceHTML(trace){return trace.map(t=>`<details class="trace"><summary>${esc(t.name)} · ${when(t.at)}</summary><pre>${esc(JSON.stringify({arguments:t.args,result:t.result},null,2))}</pre></details>`).join('');}
function agent(){const options=providerChoices();return head('AI Agent','Ask the Agent to inspect imported records and explain findings with source references.',btn('Refresh model connection','providers'))+
 (!options?`<div class="intro-line amber">${esc(providers?.ollama.message||'Checking the local model service…')} <a href="#connections">Connection details</a></div>`:'')+
 card('Prepare a review draft',`<form id="agent-form"><label class="field">Model<select name="model" required ${options?'':'disabled'}>${options||'<option>No model connected</option>'}</select></label><label class="field agent-prompt">Request<textarea name="question" maxlength="2000" required>${esc(questionDraft)}</textarea></label><div class="import-actions"><button class="btn primary" type="submit" ${options&&role==='finance'&&!runs.some(r=>r.status==='running')?'':'disabled'}>Run Agent</button><span class="muted">${role!=='finance'?'Switch to Finance reviewer to run the Agent.':'The Agent can read data and save a draft. It cannot approve or change records.'}</span></div></form>`)+
 card('Agent activity',runs.length?runs.map(r=>`<article class="run-card"><div class="card-head"><div><h3>${esc(r.question)}</h3><p>${esc(r.provider)} · ${esc(r.model)} · data v${r.revision} · ${when(r.startedAt)}</p></div>${badge(r.status,r.status==='completed'?'success':r.status==='failed'?'danger':'blue')}</div><div class="card-body">${r.status==='running'?'<p role="status">Model is working. Tool calls appear below as they finish. A local CPU run can take several minutes.</p>':''}${r.error?`<p class="form-error">${esc(r.error)}</p>`:''}${r.answer?`<div class="agent-answer">${esc(r.answer)}</div><p class="footnote">Draft saved in Reports & approvals. Source ID validation confirms that cited rows exist; it does not verify every generated statement.</p>`:''}${(r.validationNotes||[]).map(n=>`<p class="footnote">${esc(n.message)}</p>`).join('')}${traceHTML(r.trace)}</div></article>`).join(''):'<p class="muted">No Agent runs yet. A disconnected model never produces a simulated AI answer.</p>');}
function reportPaper(r){return `<article class="paper"><div class="paper-kicker">PEOPLELEDGER / REVIEW DRAFT</div><h2>Integrated HR & Finance Review</h2><div class="paper-meta">${badge(statuses[r.status])}<span>${esc(r.mode==='ai'?`${r.provider} · ${r.model}`:'Deterministic rules · No AI')}</span><span>Data v${r.revision} · ${when(r.createdAt)}</span></div><div class="agent-answer">${esc(r.answer)}</div><div class="paper-summary"><div><small>Expected payroll / SGD</small><strong>${money(r.analysis.payroll.expected)}</strong></div><div><small>Ledger income / SGD</small><strong>${money(r.analysis.finance.income)}</strong></div><div><small>Ledger expense / SGD</small><strong>${money(r.analysis.finance.expense)}</strong></div></div><h3>Deterministic findings (${r.analysis.issues.length})</h3>${findings(r.analysis)}<h3>Human decisions</h3>${r.decisions.length?r.decisions.map(d=>`<div class="decision"><strong>${esc(d.role)} · ${esc(d.action)}</strong><p>${esc(d.note)}</p><small>${when(d.at)}</small></div>`).join(''):'<p class="muted">No decisions recorded.</p>'}<h3>Source snapshot</h3><p>${Object.entries(r.snapshot.datasets).map(([k,rows])=>`${labels[k]}: ${rows.length}`).join(' · ')} · ${r.snapshot.evidence.length} evidence files</p><details><summary>View imported source rows</summary><pre>${esc(JSON.stringify(r.snapshot.datasets,null,2))}</pre></details>${r.trace?.length?`<h3>Agent tool trace</h3>${traceHTML(r.trace)}`:''}<p class="scope">Checks cover the configured rules and exact file matches. File hashes show integrity, not authenticity. The AI draft is unverified narrative. Reviewer roles are simulated in this single-user workspace. No payment, filing or external message is sent.</p></article>`;}
function reports(){let r=state.reports.find(r=>r.id===selectedReport)||state.reports[0];if(!r)return head('Reports & approvals','Review drafts and retain the data snapshot behind each decision.')+card('No reports yet','<p>Run the Agent or create a deterministic report from Reconciliation.</p>');selectedReport=r.id;const current=r.revision===state.revision;return head('Reports & approvals','Finance reviews first, then the director approves or returns the draft.')+`<div class="report-layout"><div class="report-list">${state.reports.map(x=>`<button class="report-item ${x.id===r.id?'active':''}" data-action="select-report" data-id="${x.id}"><strong>${x.mode==='ai'?'AI draft':'Rule report'} · v${x.revision}</strong><small>${when(x.createdAt)}</small>${badge(statuses[x.status])}${x.revision!==state.revision?'<small>Historical data</small>':''}</button>`).join('')}</div><div><div class="report-actionbar">${r.status==='draft'?btn('Review & submit','decision',`data-kind="review" ${role==='finance'&&current&&!r.analysis.issues.length?'':'disabled'}`,true):''}${r.status==='reviewed'?btn('Approve','decision',`data-kind="approve" ${role==='director'&&current?'':'disabled'}`,true)+btn('Return','decision',`data-kind="reject" ${role==='director'&&current?'':'disabled'}`):''}${btn('Print / Save PDF','print')}<span class="muted">${!current?'Source data changed. Create a new draft.':r.analysis.issues.length?'Resolve findings and create a new draft before review.':'Decisions require notes and the responsible reviewer role.'}</span></div>${reportPaper(r)}</div></div>`;}
function evidence(){return head('Evidence & history','Attach supporting documents by reference and export the complete review record.',btn('Export review JSON','export', '',true))+
 card('Upload supporting evidence',`<form id="evidence-form"><div class="form-grid"><label class="field">Evidence reference<input name="id" required pattern="[A-Za-z0-9_-]{1,80}" placeholder="PAY-202609-001"></label><label class="field">PDF, PNG or JPEG<input name="file" type="file" accept=".pdf,.png,.jpg,.jpeg" required></label></div><div class="import-actions"><button class="btn primary" type="submit" ${['hr','finance'].includes(role)?'':'disabled'}>Upload evidence</button><a href="/examples/evidence-examples.zip" download>Download fictional example receipts</a></div><p class="footnote">Use the exact evidence reference entered in your payroll or ledger row. File limit: 5 MB. Files are stored on this computer, with SHA-256 hashes; authenticity is not verified.</p></form>`)+
 card('Stored evidence',state.evidence.length?`<div class="table-wrap"><table><thead><tr><th>Reference</th><th>File</th><th>SHA-256</th></tr></thead><tbody>${state.evidence.map(e=>`<tr><td>${esc(e.id)}</td><td><a href="/api/evidence/${encodeURIComponent(e.id)}" download>${esc(e.filename)}</a></td><td><code title="${e.hash}">${e.hash.slice(0,18)}…</code></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No supporting files uploaded.</p>')+
 card('Activity history',state.events.length?state.events.slice().reverse().map(e=>`<div class="timeline-item"><time>${when(e.at)}<br>Data v${e.revision}</time><div><p>${esc(e.action)}</p>${e.before?`<details><summary>Before / after</summary><pre>${esc(JSON.stringify({before:e.before,after:e.after},null,2))}</pre></details>`:''}</div></div>`).join(''):'<p class="muted">No changes yet.</p>');}
function connections(){const live=runs.some(r=>r.provider==='ollama'&&r.status==='completed');return head('Connections','Connection states distinguish working file flows, configured adapters and unconnected systems.',btn('Check connections','providers'))+
 card('Available integrations',`<div class="connection-line"><div><h3>Excel / CSV → local database</h3><p>Payroll, financial ledger and bank statements. Preview, validation, version history and persisted records.</p></div>${badge('Available','success')}</div><div class="connection-line"><div><h3>Ollama local AI</h3><p>${esc(providers?.ollama.message||'Checking…')}</p><p>${esc(providers?.ollama.models.join(', ')||'No installed model detected')}</p></div>${badge(live?'Live run verified':providers?.ollama.models.length?'Model available':'Not connected',live?'success':'')}</div><div class="connection-line"><div><h3>Amazon Bedrock</h3><p>Server adapter implemented. Requires your AWS account, model access and credentials.</p></div>${badge(runs.some(r=>r.provider==='bedrock'&&r.status==='completed')?'Live run verified':providers?.bedrock.status==='configured_unverified'?'Configured, unverified':'Not connected')}</div>`)+
 card('Further project integrations',`<div class="connection-line"><div><h3>Microsoft Teams / calendar</h3><p>Requires a Microsoft 365 tenant and granted access. Scheduling connector is not implemented.</p></div>${badge('Not implemented')}</div><div class="connection-line"><div><h3>Recruitment / MyCareersFuture</h3><p>Job posting, candidate screening and interview workflow remain outside this version.</p></div>${badge('Not implemented')}</div><div class="connection-line"><div><h3>ERP / accounting system</h3><p>File-based import is available. Direct Xero, QuickBooks or ERP account sync is not connected.</p></div>${badge('Files only','blue')}</div><div class="connection-line"><div><h3>CPF / tax / regulatory filing</h3><p>No live statutory calculation or government submission.</p></div>${badge('Not implemented')}</div>`)+
 card('Local model setup',`<p>Install Ollama, start it with cloud features disabled, and download a model that supports tools. Then select the model in AI Agent.</p><pre>OLLAMA_NO_CLOUD=1 OLLAMA_GO_TEMPLATE=0 ollama serve\nollama pull qwen3:4b-instruct</pre><p class="footnote">Keep the Ollama service running while using the Agent. The source repository contains detailed setup instructions. Local data is sent to AWS only if you explicitly choose the AWS provider.</p>`);}
function render(){if(!state)return;const v=view();$('#main').innerHTML=({overview,imports,checks,agent,reports,evidence,connections})[v]();$('#crumb').textContent=names[v];document.title=names[v]+' · PeopleLedger';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===v);if(a.dataset.view===v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});}
function modal(title,body,actions=''){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2>${btn('Close','close')}</div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
async function fileContent(file){if(!file||!file.size||file.size>5*1024*1024)throw new Error('Choose a file between 1 byte and 5 MB');return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=()=>reject(new Error('Could not read file'));r.onload=()=>resolve(String(r.result).split(',')[1]);r.readAsDataURL(file);});}
async function previewImport(sheet){const r=await api('import/preview',{...upload,sheet});if(r.needsSheet){modal('Choose a worksheet',`<label class="field">Worksheet<select id="sheet">${r.sheets.map(s=>`<option>${esc(s)}</option>`).join('')}</select></label>`,btn('Preview worksheet','sheet','',true));return;}preview=r;modal('Confirm '+labels[r.kind]+' import',`<p>Replace ${r.previousCount} current records with ${r.rows.length} validated rows from ${esc(r.filename)}. Existing reports and import history will remain.</p><p class="footnote">SHA-256: ${r.hash}</p>${table(r.rows.slice(0,5),schemas[r.kind])}<p class="footnote">First ${Math.min(5,r.rows.length)} rows shown. Nothing has been saved yet.</p>`,btn('Confirm replacement','commit','',true));}
async function loadProviders(){providers=await api('providers');if(['agent','connections'].includes(view()))render();}
async function loadRuns(){runs=await api('runs');if(view()==='agent')render();clearTimeout(pollTimer);if(runs.some(r=>r.status==='running'))pollTimer=setTimeout(()=>loadRuns().catch(e=>toast(e.message,true)),2500);else await refresh();}
async function mutate(path,payload){await api(path,{...payload,revision:state.revision,role});await refresh();}
function editRecord(id){const r=state.datasets[kind].find(r=>r.id===id);modal('Edit '+id,`<form id="edit-form"><input type="hidden" name="id" value="${esc(id)}"><div class="form-grid">${schemas[kind].filter(k=>k!=='id').map(k=>`<label class="field">${k}<input name="${k}" value="${esc(r[k])}"></label>`).join('')}<label class="field full">Change explanation<textarea name="note" required maxlength="1000"></textarea></label></div><div class="import-actions"><button class="btn primary" type="submit">Save changes</button></div></form>`);}
async function action(b){const a=b.dataset.action;
 if(a==='nav')return navigate(b.dataset.view);if(a==='close')return $('#modal').close();
 if(a==='providers')return loadProviders();if(a==='edit')return editRecord(b.dataset.id);
 if(a==='sheet')return previewImport($('#sheet').value);
 if(a==='commit'){await api('import/commit',{id:preview.id,role});$('#modal').close();await refresh();toast('File imported and saved.');}
 if(a==='rule-report'){await mutate('reports/rules',{});navigate('reports');}
 if(a==='select-report'){selectedReport=b.dataset.id;render();}
 if(a==='decision'){modal('Record '+b.dataset.kind,`<form id="decision-form"><input name="action" type="hidden" value="${b.dataset.kind}"><label class="field">Review notes<textarea name="note" maxlength="1000" required></textarea></label><div class="import-actions"><button class="btn primary" type="submit">Save decision</button></div></form>`);}
 if(a==='print'){const r=state.reports.find(r=>r.id===selectedReport);$('#print-area').innerHTML=reportPaper(r);window.print();}
 if(a==='payroll-csv'){const url=URL.createObjectURL(new Blob([window.ComplianceEngine.toCSV(state.datasets.payroll)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`people-ledger-payroll-v${state.revision}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 if(a==='export'){const data=await api('export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`people-ledger-review-v${state.revision}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
async function submit(f){const p=Object.fromEntries(new FormData(f)),formId=f.getAttribute('id');
 // Named form controls can shadow DOM properties, including the form's id.
 if(formId==='import-form'){kind=p.kind;upload={kind,filename:p.file.name,content:await fileContent(p.file)};await previewImport();}
 if(formId==='evidence-form'){await mutate('evidence',{id:p.id,filename:p.file.name,content:await fileContent(p.file)});toast('Evidence file saved.');}
 if(formId==='edit-form'){const {id,note,...changes}=p;await mutate('records/edit',{kind,id,note,changes});$('#modal').close();toast('Changes saved. Previous reports are historical.');}
 if(formId==='decision-form'){await mutate('reports/decision',{id:selectedReport,...p});$('#modal').close();toast('Decision recorded.');}
 if(formId==='agent-form'){const [provider,...model]=p.model.split('|');await mutate('agent/run',{provider,model:model.join('|'),question:p.question});await loadRuns();}
}
 document.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b||b.disabled)return;try{b.disabled=true;await action(b);}catch(e){toast(e.message,true);}finally{if(b.isConnected)b.disabled=false;}});
 document.addEventListener('submit',async e=>{if(!e.target.matches('#import-form,#agent-form,#evidence-form,#edit-form,#decision-form'))return;e.preventDefault();if(busy)return;busy=true;const buttons=[...e.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await submit(e.target);}catch(e){toast(e.message,true);}finally{busy=false;buttons.forEach(b=>{if(b.isConnected)b.disabled=false;});}});
 document.addEventListener('input',e=>{if(e.target.name==='question')questionDraft=e.target.value;});
 document.addEventListener('change',e=>{if(e.target.id==='dataset'){kind=e.target.value;render();}});
 $('#role').addEventListener('change',e=>{role=e.target.value;render();});
 window.addEventListener('hashchange',()=>{render();if(['agent','connections'].includes(view()))loadProviders().catch(e=>toast(e.message,true));window.scrollTo(0,0);});
 refresh().then(()=>Promise.all([loadProviders(),loadRuns()])).catch(e=>{$('#main').innerHTML=head('Start the local workspace','This version needs its backend to import files, save evidence and run the Agent.')+card('Connection unavailable',`<p>${esc(e.message)}</p><pre>npm install\nnpm start</pre><p>Open the address printed by the server. A static web upload cannot run this version.</p>`);});
})();
